INSERT INTO `itineraries` (`itinerary_id`, `created_at`, `updated_at`, `day_number`, `description`, `title`, `tour_id`) VALUES
(1, '2026-01-03 09:01:00.000000', '2026-01-03 09:01:00.000000', 1, '<p><b>Sáng:</b> Xe/đoàn đón khách tại điểm hẹn, khởi hành Hang Sửng Sốt.</p><p><b>Chiều:</b> Tham quan Đảo Ti Tốp, tự do chụp ảnh.</p><p><b>Tối:</b> Ăn tối, nghỉ đêm tại khách sạn.</p>', 'Hà Nội – Vịnh Hạ Long', 1),
(2, '2026-01-03 09:01:00.000000', '2026-01-03 09:01:00.000000', 2, '<p><b>Sáng:</b> Ăn sáng tại khách sạn, tham quan Đảo Ti Tốp.</p><p><b>Chiều:</b> Tham quan Làng chài Cửa Vạn, tự do chụp ảnh.</p><p><b>Tối:</b> Về điểm đón ban đầu, kết thúc chương trình.</p>', 'Làng chài Cửa Vạn – Hà Nội', 1),
(3, '2026-01-03 09:02:00.000000', '2026-01-03 09:02:00.000000', 1, '<p><b>Sáng:</b> Xe/đoàn đón khách tại điểm hẹn, khởi hành Đỉnh Fansipan.</p><p><b>Chiều:</b> Tham quan Thung lũng Mường Hoa, tự do chụp ảnh.</p><p><b>Tối:</b> Ăn tối, nghỉ đêm tại khách sạn.</p>', 'Hà Nội – Bản Cát Cát', 2),
(4, '2026-01-03 09:02:00.000000', '2026-01-03 09:02:00.000000', 2, '<p><b>Sáng:</b> Ăn sáng tại khách sạn, tham quan Thung lũng Mường Hoa.</p><p><b>Chiều:</b> Tham quan Nhà thờ Đá Sa Pa, tự do chụp ảnh.</p><p><b>Tối:</b> Ăn tối, nghỉ đêm tại khách sạn.</p>', 'Thung lũng Mường Hoa – Nhà thờ Đá Sa Pa', 2),
(5, '2026-01-03 09:02:00.000000', '2026-01-03 09:02:00.000000', 3, '<p><b>Sáng:</b> Ăn sáng tại khách sạn, tham quan Nhà thờ Đá Sa Pa.</p><p><b>Chiều:</b> Tham quan Đèo Ô Quy Hồ, tự do chụp ảnh.</p><p><b>Tối:</b> Về điểm đón ban đầu, kết thúc chương trình.</p>', 'Đèo Ô Quy Hồ – Hà Nội', 2),
