INSERT INTO `reviews` (`id`, `created_at`, `updated_at`, `admin_response`, `comment`, `is_hidden`, `hidden_reason`, `rating`, `booking_id`) VALUES
(1, '2026-01-23 09:21:00.000000', '2026-01-24 06:21:00.000000', 'Cảm ơn Quý khách đã dành thời gian chia sẻ. Chúc Quý khách và gia đình luôn vui khoẻ!', 'Chuyến đi rất tuyệt, hướng dẫn viên nhiệt tình, chu đáo.', b'0', NULL, 4, 2),
(2, '2026-02-16 17:11:00.000000', '2026-02-16 17:11:00.000000', NULL, 'Cảnh đẹp xuất sắc, cả gia đình đều rất hài lòng.', b'0', NULL, 4, 4),
(3, '2026-02-15 16:51:00.000000', '2026-02-17 12:51:00.000000', 'VietTrip cảm ơn Quý khách đã tin tưởng! Hẹn gặp lại Quý khách ở những hành trình tiếp theo.', 'Cảnh đẹp xuất sắc, cả gia đình đều rất hài lòng.', b'0', NULL, 5, 5),
